async function provisionInitialAccounts(){
 let changed=false;
 // Production bootstrap is explicit; credentials are never stored in code.
 if(!demo&&process.env.BOOTSTRAP_ADMIN_USERNAME&&process.env.BOOTSTRAP_ADMIN_PASSWORD&&!store.data.users.some(u=>u.username===process.env.BOOTSTRAP_ADMIN_USERNAME)){
  store.data.users.push({id:makeId('USR'),username:process.env.BOOTSTRAP_ADMIN_USERNAME,passwordHash:pwHash(process.env.BOOTSTRAP_ADMIN_PASSWORD),role:'ADMIN',phone:null,displayName:process.env.BOOTSTRAP_ADMIN_NAME||'Workspace administrator',candidateId:null,createdAt:new Date().toISOString()});changed=true;
 }
 // Fixed credentials are intentionally available only in demo mode.
 if(demo){
  for(const item of [{username:'assessor1',password:'Assess@123',role:'ASSESSOR' as Role,displayName:'Demo assessor'},{username:'admin',password:'Admin@123',role:'ADMIN' as Role,displayName:'Demo administrator'}]){
   const existing=store.data.users.find(u=>u.username===item.username&&u.role!=='WORKER');
   if(existing){if(!existing.passwordHash){existing.passwordHash=pwHash(item.password);changed=true}if(item.role==='ASSESSOR'&&!existing.authorizedOccupationIds){existing.authorizedOccupationIds=[occupationId(content)];changed=true}}
   else{store.data.users.push({id:makeId('USR'),username:item.username,passwordHash:pwHash(item.password),role:item.role,phone:null,displayName:item.displayName,candidateId:null,...(item.role==='ASSESSOR'?{authorizedOccupationIds:[occupationId(content)]}:{}),createdAt:new Date().toISOString()});changed=true}
  }
  for(const phone of ['0000000000','0000000001'])if(!store.data.users.some(u=>u.role==='WORKER'&&u.phone===phone)){
   store.data.users.push({id:makeId('USR'),username:null,passwordHash:null,role:'WORKER',phone,displayName:'Skill Holder',candidateId:null,createdAt:new Date().toISOString()});changed=true;
  }
 }
 if(changed)await store.save();
}
