app.get(
  '/api/admin/occupations/:id/content',
  requireRole('ADMIN', 'REVIEWER'),
  (req, res) => {
    const id = String(req.params.id);
    const source = contentRegistry.byOccupation(id), selected = source ? bundleWithReviews(source) : undefined;

    if (!selected) {
      return res.status(404).json({
        error: 'Occupation content not found',
      });
    }

    res.json({
      contentSet: selected.contentSet,
      occupationId: occupationId(selected),
      occupations: contentRegistry.occupations(
        store.data.occupationAvailability
      ),
      qualificationPacks: selected.qualificationPacks,
      standards: selected.standards,
      taskMappings: selected.taskMappings,
      performanceCriteria: selected.performanceCriteria,
      tasks: taskOptionsFor(selected),
      vivaQuestions: selected.vivaQuestions,
      practicalAssessmentTasks: selected.practicalAssessmentTasks,
      assessmentMetadata: selected.assessmentMetadata || null,
      candidates: selected.candidates,
      assessmentExamples: selected.assessmentExamples,
      calibrationCases: selected.calibrationCases,
      calibrationScores: selected.calibrationScores,
      bridgeRecommendations: selected.bridgeRecommendations,
      mappingValidation: validateQualificationBundle(selected),
      mappingCounts: mappingCounts(selected),
      synthetic:
        selected.contentSet.classification === 'SYNTHETIC_DEMO',
    });
  }
);

