  if(!canReleaseLegacyAdminAssignment(actor.role,a.status,draft.users.find(item=>item.id===a.assessorId)?.role))throw new Error('This legacy assignment has already changed');
  const previousAssessorId=a.assessorId;a.assessorId=null;a.status='REQUESTED';a.updatedAt=new Date().toISOString();
  const admin=draft.users.find(item=>item.id===actor.id);
