app.post('/api/admin/demo-review/review',requireRole('REVIEWER','ADMIN'),(req,res)=>{
 if(!demo)return res.status(404).json({error:'The synthetic review demonstration is available only in local demo mode'});
 const decision=req.body?.decision,reason=String(req.body?.reason||'').trim();
 if(req.body?.reportId!==adminPendingReviewFixture.id||Number(req.body?.reportVersion)!==adminPendingReviewFixture.version)return res.status(409).json({error:'This synthetic report version is stale or does not match the pending demo report.'});
 if(!['APPROVED','RETURNED'].includes(decision))return res.status(400).json({error:'Decision must be APPROVED or RETURNED'});
 if(decision==='RETURNED'&&reason.length<3)return res.status(400).json({error:'Provide a correction explanation of at least 3 characters'});
 const actor=user(req)!;adminPendingReviewState.decision=decision;adminPendingReviewState.reason=decision==='RETURNED'?reason.slice(0,2000):'';adminPendingReviewState.reviewedAt=new Date().toISOString();adminPendingReviewState.reviewerRole=actor.role as 'ADMIN'|'REVIEWER';
 res.json(adminPendingReviewView());
});
app.post('/api/admin/demo-review/reset',requireRole('REVIEWER','ADMIN'),(req,res)=>{
 if(!demo)return res.status(404).json({error:'The synthetic review demonstration is available only in local demo mode'});
 adminPendingReviewState.decision=null;adminPendingReviewState.reason='';adminPendingReviewState.reviewedAt=null;adminPendingReviewState.reviewerRole=null;
 res.json(adminPendingReviewView());
});
app.get('/api/reports/:id/preview',requireRole('WORKER','ASSESSOR','REVIEWER','ADMIN'),(req,res)=>{
 const context=authorizedReport(req,res);if(!context||'statusCode'in context)return;
 const {report,assessment}=context,snapshot=reportSnapshotFor(report,assessment),snapshotHash=snapshot.profileNameRecovered?undefined:(report.snapshotHash||createHash('sha256').update(JSON.stringify(snapshot)).digest('hex'));
 const html=reportPreviewHtml(snapshot,report.status,report.assessorSignoff,report.reviewerSignoff,snapshotHash,`/api/assessments/${assessment.id}/evidence/`,`/api/reports/${report.id}/download`);
 res.type('html').send(html);
});
